import{_ as i,l as o,o as e,c as n,v as t,p as l,x as s,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"集合与关系","description":"","frontmatter":{"title":"集合与关系","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sets-relations.md","filePath":"cs/sets-relations.md","lastUpdated":1789023840000}'),h={name:"cs/sets-relations.md"};function E(m,a,_,A,u,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="集合与关系" tabindex="-1">集合与关系 <a class="header-anchor" href="#集合与关系" aria-label="Permalink to &quot;集合与关系&quot;">​</a></h1><div class="epigraph"><p>把对象收成集合，把「谁连着谁」写成有序对的集合，后面的函数、图和归纳才有载体。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/static-dynamic-hazard">静态与动态险象</a>把组合逻辑的手算化简收到头：函数、无关项、毛刺都在布尔格子上。本课不重画卡诺图，也不从「数学基础」另起一篇集合论。缺口是：后课要谈可数、图、树、概率，对象不再是 \\(n\\) 个比特的真值表。需要一套更瘦的语言：<strong>集合</strong>，以及集合上的<strong>关系</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布尔函数是 \\(\\{0,1\\}^n\\) 到 \\(\\{0,1\\}\\) 的对应。图的边、偏序、后课的「可达」，都不是「输出比特」。缺口因此不是新的门，而是：从论域 \\(A\\) 取出子集，再在 \\(A\\times B\\) 上取出哪些有序对算「有关系」。关系可以自反、对称、传递；等价关系诱导划分；偏序才谈得上拓扑与后课 DAG。</p><p>本课只钉这些定义。函数是特殊关系，下一课才加单射、满射、可数。电路不再在本课出现。</p><h3 id="关系不是「两个集合有联系」的散文" tabindex="-1">关系不是「两个集合有联系」的散文 <a class="header-anchor" href="#关系不是「两个集合有联系」的散文" aria-label="Permalink to &quot;关系不是「两个集合有联系」的散文&quot;">​</a></h3><p>\\(R\\subseteq A\\times A\\) 是确定的集合。说「朋友关系」却不给出有序对，后课图论没有边集。有序对 \\((a,b)\\) 与 \\(\\{a,b\\}\\) 不同：有向与无向在这里已经分叉，<a href="/cs/graph-definition">图的定义</a>会分别写。</p><p><span class="marginnote">Rosen 用关系矩阵与有向图当同一关系的两种像。本课不把矩阵乘法当复合的算法分析，只要求复合 \\(S\\circ R\\) 仍是关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外延公理：集合由元素决定。幂集、笛卡尔积按常规定义。关系的性质逐条检查，不混用：「对称且传递却不自反」可能发生在空关系等边角，本课不靠边角讲课，主干用等价 \\(\\Leftrightarrow\\) 划分。</p>',11)),(e(),l(c,null,{default:s(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E9%9B%86%E5%90%88%22%5D%20--%3E%20REL%5B%22%E5%85%B3%E7%B3%BB%20%E2%8A%86%20A%C3%97B%22%5D%0A%20%20REL%20--%3E%20EQ%5B%22%E7%AD%89%E4%BB%B7%20%E2%86%92%20%E5%88%92%E5%88%86%22%5D%0A%20%20REL%20--%3E%20PO%5B%22%E5%81%8F%E5%BA%8F%22%5D%0A%20%20REL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%87%BD%E6%95%B0%E4%B8%8E%E5%8F%AF%E6%95%B0%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课图 \\(G=(V,E)\\) 就是 \\(E\\) 作为关系（无向则要求对称且通常无自环）。等价关系给「同余、同一连通分量」提供语言。布尔代数可以解释成某集合的幂集运算，那是解释，不是本课要把门再讲一遍。</p><p>有限与无限在本课只作区分：有限集可与 \\(\\{1,\\ldots,n\\}\\) 双射。真正的可数、不可数是下一课。归纳需要自然数，也还没进场。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论选择公理、基数算术的争议，不把 Russell 悖论展开成课程。也不把关系数据库提前到本栏数据库课：关系在这里是离散数学对象；Codd 的关系模型是很后面的叶子。</p><p>后课默认：谈到「一对对象是否相关」，先给出 \\(R\\) 作为集合。图、函数、序都从这里长出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>集合由元素确定；关系是有序对的集合。</li><li>等价对应划分；偏序是后课 DAG 的序来源之一。</li><li>函数、可数、图都是本课之后的特化，不在本课重讲门。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',8))])}const T=i(h,[["render",E]]);export{b as __pageData,T as default};
